INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷八十二", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/33c4505fd076635fd33c0ce1412ecfa289823f13/content/books/zizhi-tongjian/vol-284/year-0944/part-02/sources/library/jiuwudaishi-082-944-april/source.txt", "note": "《旧五代史》卷八十二，段落 jiu-wudaishi-205deb4a7860-p002002；EPUB电子本，纸本及异文待核", "id": "50d9bbb6-3cbd-5348-89a6-8d324e8d5f31"}, {"title": "辽史·卷四", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/33c4505fd076635fd33c0ce1412ecfa289823f13/content/books/zizhi-tongjian/vol-284/year-0944/part-02/sources/library/liaoshi-004-944-march/source.txt", "note": "《辽史》卷四，段落 liaoshi-7cd182a20e67-p000543；EPUB电子本，纸本及异文待核", "id": "48cc77af-34a5-5bcf-a9d9-dcd8a5436cfb"}, {"title": "资治通鉴·后晋纪五", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/33c4505fd076635fd33c0ce1412ecfa289823f13/content/books/zizhi-tongjian/vol-284/year-0944/part-02/sources/library/tongjian-284-944-march-april/source.txt", "note": "《资治通鉴》后晋纪五，段落 zizhi-tongjian-a63549944a71-p003374；电子底本待考，分段待核", "id": "99e29f0d-e4d8-5ae2-ac0a-8a7a69199903"}, {"title": "新五代史·卷六十五", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/33c4505fd076635fd33c0ce1412ecfa289823f13/content/books/zizhi-tongjian/vol-284/year-0944/part-02/sources/library/xinwudaishi-065-hongchang-death/source.txt", "note": "《新五代史》卷六十五，段落 xin-wudaishi-b08f244b9241-p003282；EPUB电子本，纸本及异文待核", "id": "e1931bf1-56d8-5868-b373-bbb8e29e25fc"}, {"title": "新五代史·卷六十八", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/33c4505fd076635fd33c0ce1412ecfa289823f13/content/books/zizhi-tongjian/vol-284/year-0944/part-02/sources/library/xinwudaishi-068-zhu-wenjin/source.txt", "note": "《新五代史》卷六十八，段落 xin-wudaishi-b08f244b9241-p003413；EPUB电子本，纸本及异文待核", "id": "d890caa3-5bdd-5371-a027-7e2322c23458"}, {"title": "旧五代史·卷八十二", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/2a028697786379c39fe2e5fec2c736c49f846f9f/content/books/zizhi-tongjian/vol-284/year-0944/part-01/sources/library/jiuwudaishi-082-944-march/source.txt", "note": "《旧五代史》卷八十二，段落 jiu-wudaishi-205deb4a7860-p002001；EPUB电子本，纸本及异文待核", "id": "645b500c-7bcf-5ab3-bfdf-267b6ab11ffb"}, {"title": "新五代史·卷68·闽世家·王延羲妻李氏", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d7e9f7a7ea4b22cbbe6d05277dd5c16ed51a9e06/content/books/zizhi-tongjian/vol-283/year-0942/part-01/sources/library/xinwudaishi-068-min-li-empress/source.txt", "note": "《新五代史》卷68·闽世家·王延羲妻李氏，段落 xin-wudaishi-b08f244b9241-p003411；已核上下文及传主，纸本及异文待核。", "id": "f65572e7-91e0-5d18-a84c-68aa6429f9d4"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "刘弘熙", "aliases": ["劉弘熙", "刘洪熙", "劉洪熙"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘熙，获封王爵之子。", "biography": null, "status": "draft", "id": "b67079e8-6ec8-5150-9451-5b3ce7983fec"}, {"name": "刘弘昌", "aliases": ["劉弘昌", "刘洪昌", "劉洪昌"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘昌，获封王爵之子。", "biography": null, "status": "draft", "id": "fda27388-00bf-5390-90ae-9604e2ec1c33"}, {"name": "耶律德光", "aliases": ["德光"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：耶律德光，守西楼、受号者。", "biography": null, "status": "draft", "id": "64c415ac-57fe-571c-8c6f-3ed68fb726da"}, {"name": "赵延照", "aliases": ["趙延照"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "赵思温的儿子。《资治通鉴》记载，他在后晋任祁州刺史，并受父亲委托向石敬瑭转达幽州归附的请求。相关行动的具体年份未载。", "biography": null, "status": "draft", "id": "a3905a7c-cc29-5e76-a63f-eede596759ff"}, {"name": "麻答", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹将领，《资治通鉴》称为耶律德光的从弟。944年二月由周儒引导从马家口渡河，攻郓州北津，以接应杨光远。个人其他名字及生卒年本批未核。", "biography": null, "status": "draft", "id": "5911d4cb-fa8a-51ff-a1e4-44450396116a"}, {"name": "尹居璠", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋德州刺史。944年契丹北归期间，麻答攻陷德州，尹居璠被擒。《旧五代史》四月条载沧州奏报此事；被俘不记为死亡。生卒年未载。", "biography": null, "status": "draft", "id": "8000d2b3-a15d-5e5f-956c-b8522de1068e"}, {"name": "朱文进", "aliases": ["硃文进", "朱文進", "硃文進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "永泰人，闽国拱宸军将领。《资治通鉴》记他与连重遇多次受王继鹏侮辱而心怀不满，《新五代史》还记二人因宸卫军待遇优厚而激怒部众。生卒年未载。", "biography": null, "status": "draft", "id": "309ef83c-46fe-51a1-86cc-c2cb8dc48d82"}, {"name": "连重遇", "aliases": ["連重遇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "光山人，闽国控鹤军将领。939年率拱宸、控鹤军起兵攻击王继鹏，拥立王延羲。生卒年未载。", "biography": null, "status": "draft", "id": "5f02df46-1b50-5419-8220-ef50fe37c3eb"}, {"name": "王延羲", "aliases": ["王曦"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国宗室，王继鹏的叔父，曾任左仆射、同平章事。939年被政变军队拥立，自称威武节度使、闽国王，更名王曦，改元永隆。生卒年暂未核实。", "biography": null, "status": "draft", "id": "e706d6ae-56f4-5e44-9d24-f3060ae87cbb"}, {"name": "魏从朗", "aliases": ["魏從朗"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国控鹤指挥使，史书记为朱文进、连重遇的党人。王延羲游西园饮醉后将他杀死，具体年月未载。未将党人直接解释为永久盟友关系。", "biography": null, "status": "draft", "id": "efed05f2-7243-5511-8b00-446ee16b3a2d"}, {"name": "李氏（王延羲后）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国同平章事李真的女儿，王延羲的妻子。942年被立为皇后。《资治通鉴》和《新五代史》都记她嗜酒，性格强硬。姓名及生卒年未载。", "biography": null, "status": "draft", "id": "eb943b54-1a2c-5d87-8764-6486416880c7"}, {"name": "王亚澄", "aliases": ["王亞澄"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽王王延羲的儿子。941年四月被任命为同平章事，主管六军诸卫。生卒年未载。", "biography": null, "status": "draft", "id": "bdfe7b21-c8f9-5a2a-8792-e061e8da5652"}, {"name": "李真", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国官员。939年王延羲即位后，将已以太子太傅身份退休的李真任为司空兼中书侍郎、同平章事。生卒年未载。", "biography": null, "status": "draft", "id": "be8de9d6-a061-55a2-9434-5f7e8c2a8702"}, {"name": "钱达", "aliases": ["錢達"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国拱宸马步使。944年三月乙酉，受朱文进、连重遇指使，在王延羲探望李真的途中将其在马上杀死。生卒年未载。", "biography": null, "status": "draft", "id": "4b1c8bd9-ef83-5823-ba43-5928366ff5af"}, {"name": "王延喜", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽王王延羲的弟弟，汀州刺史。941年四月王延羲怀疑他与王延政串通，派许仁钦率兵将他拘捕带回。串通是王延羲的怀疑，原文没有确认。生卒年未载。", "biography": null, "status": "draft", "id": "a3856e32-2a9d-5720-ac05-bb42733a3fbe"}, {"name": "郑元弼", "aliases": ["鄭元弼"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国礼部员外郎。939年奉王继恭的表章，随卢损前往后晋进贡。生卒年未载。", "biography": null, "status": "draft", "id": "a656f099-5f42-574b-bfa0-daa89cb73913"}, {"name": "王延政", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：王延政，都教练使、赴建州抚慰者。", "biography": null, "status": "draft", "id": "83601670-f3dc-5559-b599-e39bda91eb6c"}, {"name": "吴成义", "aliases": ["吳成義"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "殷国统军使。944年闽国政变后受王延政命率兵讨伐朱文进，未能攻克。后续福建战事尚随主书继续录入。生卒年未载。", "biography": null, "status": "draft", "id": "5b79c091-612f-5d81-9f36-da75ba08386b"}, {"name": "鲍思润", "aliases": ["鮑思潤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国枢密使。944年朱文进掌权后，被授予同平章事职衔。生卒年未载。", "biography": null, "status": "draft", "id": "e9170504-43f6-5ce5-a98b-df680968e953"}, {"name": "黄绍颇", "aliases": ["黃紹頗"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国官员，连江人。陈匡范借款补额一事暴露后，王延羲任黄绍颇为国计使。黄绍颇建议对不属荫补的求官者按条件收钱授官，王延羲接受。具体年月和生卒年未载。", "biography": null, "status": "draft", "id": "534bfbe9-b7bc-5b90-8054-1bb004f6b7c7"}, {"name": "程文纬", "aliases": ["程文緯"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国左军使，944年朱文进掌权后任漳州刺史。《新五代史》相同政局的漳州守将写程贇，是否同人异名待核，未直接合并。生卒年未载。", "biography": null, "status": "draft", "id": "a9868a49-25bf-55fb-829a-1e4110d2e03a"}, {"name": "许文稹", "aliases": ["許文稹", "许文缜", "許文縝"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "同安人，汀州刺史。944年朱文进掌权后率郡投降朱文进。《新五代史》对应汀州守将作許文縝，保留姓名字形异文；该书后文投降王延政为另一阶段，不混为当前投降对象。生卒年未载。", "biography": null, "status": "draft", "id": "6717f767-1ab2-52b8-8015-c778cc06ee45"}, {"name": "石重贵", "aliases": ["石重貴"], "era": "五代十国", "birth_year": 914, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：石重贵，被叙侄子及养子身份者。", "biography": null, "status": "draft", "id": "2741e60a-9bf9-56a7-b30d-3db439caa139"}, {"name": "马全节", "aliases": ["馬全節"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：马全节，金州防御使、以私财给军并拒战者。", "biography": null, "status": "draft", "id": "bb5608d9-eabe-58ce-8c56-b07e57faadb5"}, {"name": "陈偓", "aliases": ["陳偓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南汉户部侍郎。944年三月条下被任命为同平章事。生卒年未载。", "biography": null, "status": "draft", "id": "a710cc92-9e61-5cfb-b0ed-a9fa29fecd8a"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

